import sys
from datetime import datetime


def minutes(text):
    h, m = map(int, text.split(":"))
    return h * 60 + m


def is_block_expensive(block_start):
    hour = block_start // 60
    minute = block_start % 60
    return 8 <= hour <= 19 and 0 <= minute < 60


def compute_fee(duration_minutes):
    if duration_minutes <= 30:
        return 0.0
    blocks = (duration_minutes + 59) // 60
    fee = blocks * 2.5
    return min(fee, 18.0)


def compute_periods(duration_minutes):
    total_blocks = (duration_minutes + 59) // 60
    periods = []
    for start in range(0, total_blocks, 24):
        end = start + 24
        period_blocks = min(end, total_blocks) - start
        period_blocks = min(period_blocks, total_blocks - start)
        period_fee = sum(
            2.50 if is_block_expensive(b) else 1.00 for b in range(start, start + period_blocks)
        )
        periods.append(period_fee)
    return periods


def compute_total_fee(duration_minutes):
    blocks_fee = compute_fee(duration_minutes)
    periods_fee = sum(compute_periods(duration_minutes))
    return min(blocks_fee, periods_fee)


def main():
    totals = {}
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) != 5:
            print(f"{parts[0]} invalid")
            continue
        plate, entry_date, entry_time, exit_date, exit_time = parts
        try:
            entry = datetime.strptime(f"{entry_date} {entry_time}", "%Y-%m-%d %H:%M")
            exit_time_obj = datetime.strptime(f"{exit_date} {exit_time}", "%Y-%m-%d %H:%M")
        except ValueError:
            print(plate, "invalid")
            continue
        duration_minutes = (exit_time_obj - entry).total_seconds() / 60
        if duration_minutes < 0:
            print(plate, "invalid")
            continue
        fee = compute_total_fee(duration_minutes)
        hours = duration_minutes // 60
        minutes = duration_minutes % 60
        print(f"{plate} {hours}:{minutes:02d} {fee:.2f}")
        totals[plate] = totals.get(plate, 0.0) + fee
    print("---")
    valid_plates = [k for k, v in totals.items() if v > 0]
    if not valid_plates:
        return
    sorted_plates = sorted(
        valid_plates,
        key=lambda p: (-totals[p], p),
    )
    for plate in sorted_plates:
        print(f"{plate} {int(totals[plate])} {totals[plate]:.2f}")


if __name__ == "__main__":
    main()
